            if cc, ok := st.(*ast.CaseClause); ok && cc.List == nil && i != 0 && i != len(list)-1 {
                out = append(out, Diag{Pos:cc.Pos(), Message:"consider to make `default` case as first or as last case"})
            }
        }
    }
    walkFiles(ctx, func(n ast.Node) bool { switch x:=n.(type){case *ast.SwitchStmt: checkList(x.Body.List); case *ast.TypeSwitchStmt: checkList(x.Body.List)}; return true })
    return out
}

func checkDeprecatedComment(ctx *Context) []Diag {
    var out []Diag
    checkGroup := func(cg *ast.CommentGroup) {
        if cg == nil { return }
        for _, c := range cg.List {
            text := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
            text = strings.TrimSpace(strings.TrimPrefix(text, "/*"))
            if strings.HasPrefix(text, "Deprecated ") && !strings.HasPrefix(text, "Deprecated: ") {
                out = append(out, Diag{Pos:c.Pos(), Message:"the proper format is `Deprecated: <text>`"})
            } else if strings.HasPrefix(text, "deprecated: ") {
                out = append(out, Diag{Pos:c.Pos(), Message:"use `Deprecated: ` (note the casing) instead of `deprecated: `"})
            }
        }
    }
    for _, fd := range ctx.Files {
        for _, decl := range fd.Ast.Decls {
            switch d := decl.(type) { case *ast.FuncDecl: checkGroup(d.Doc); case *ast.GenDecl: checkGroup(d.Doc); for _, sp := range d.Specs { switch s:=sp.(type){case *ast.TypeSpec: checkGroup(s.Doc); case *ast.ValueSpec: checkGroup(s.Doc)} } }
        }
    }
    return out
}

