        is, ok := n.(*ast.IfStmt); if !ok || is.Else == nil { return true }
        if isPartOfElseIf(ctx, is) { return true }
        count := 0
        cur := is
        for cur.Else != nil {
            switch e := cur.Else.(type) {
            case *ast.IfStmt: count++; cur = e
            case *ast.BlockStmt: count++; cur = nil
            default: cur = nil
            }
            if cur == nil { break }
        }
        if count >= ctx.Opt.ifElseChainMinThreshold { out = append(out, Diag{Pos:is.Pos(), Message:"rewrite if-else to switch statement"}) }
        return true
    })
    return out
}
