func zeroValueForType(e ast.Expr, typ string) string {
    switch typ { case "bool": return "false"; case "string": return "\"\""; case "float32","float64": return "0.0"; case "complex64","complex128": return "0i" }
    ints := map[string]bool{"int":true,"int8":true,"int16":true,"int32":true,"int64":true,"uint":true,"uint8":true,"uint16":true,"uint32":true,"uint64":true,"uintptr":true,"byte":true,"rune":true}
    if ints[typ] { return "0" }
    switch e.(type) { case *ast.StarExpr: return fmt.Sprintf("(%s)(nil)", typ); case *ast.ArrayType: if strings.HasPrefix(typ,"[]") { return typ+"(nil)" }; return typ+"{}"; case *ast.MapType, *ast.ChanType, *ast.FuncType, *ast.InterfaceType: return typ+"(nil)" }
    return typ+"{}"
}

