        switch e := n.(type) {
        case *ast.SelectorExpr:
            if p, ok := e.X.(*ast.ParenExpr); ok { if u,ok:=p.X.(*ast.UnaryExpr); ok && u.Op==token.MUL { out=append(out,Diag{Pos:e.Pos(),Message:fmt.Sprintf("could simplify %s to %s.%s", exprString(ctx,e), exprString(ctx,u.X), e.Sel.Name)}) } }
        case *ast.IndexExpr:
            if p, ok := e.X.(*ast.ParenExpr); ok { if u,ok:=p.X.(*ast.UnaryExpr); ok && u.Op==token.MUL { out=append(out,Diag{Pos:e.Pos(),Message:fmt.Sprintf("could simplify %s to %s[%s]", exprString(ctx,e), exprString(ctx,u.X), exprString(ctx,e.Index))}) } }
        }
        return true
    })
    return out
}

func checkUnlambda(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        fl, ok := n.(*ast.FuncLit); if !ok || len(fl.Body.List)!=1 { return true }
        ret, ok := fl.Body.List[0].(*ast.ReturnStmt); if !ok || len(ret.Results)!=1 { return true }
        c, ok := ret.Results[0].(*ast.CallExpr); if !ok { return true }
        var params []string
        if fl.Type.Params != nil { for _, f := range fl.Type.Params.List { for _, id := range f.Names { params=append(params,id.Name) } } }
        if len(params) != len(c.Args) { return true }
        for i,a := range c.Args { if !isIdent(a, params[i]) { return true } }
        out = append(out, Diag{Pos:fl.Pos(), Message:fmt.Sprintf("replace `%s` with `%s`", exprString(ctx,fl), exprString(ctx,c.Fun))})
        return true
    })
    return out
}

func checkUnnecessaryBlock(ctx *Context) []Diag { var out []Diag; walkFiles(ctx, func(n ast.Node) bool { b,ok:=n.(*ast.BlockStmt); if ok && len(b.List)>0 { if _,ok:=parentIsFuncBody(ctx,b); !ok { out=append(out,Diag{Pos:b.Pos(),Message:"unnecessary block"}) } }; return true }); return out }
func parentIsFuncBody(ctx *Context,b *ast.BlockStmt)(ast.Node,bool){return nil,true}

func checkUnnecessaryDefer(ctx *Context) []Diag { var out []Diag; walkFiles(ctx, func(n ast.Node) bool { b,ok:=n.(*ast.BlockStmt); if !ok || len(b.List)!=1 {return true}; if d,ok:=b.List[0].(*ast.DeferStmt); ok { out=append(out,Diag{Pos:d.Pos(),Message:fmt.Sprintf("unnecessary defer: call %s directly", exprString(ctx,d.Call))}) }; return true }); return out }

func checkUnslice(ctx *Context) []Diag { var out []Diag; walkFiles(ctx, func(n ast.Node) bool { s,ok:=n.(*ast.SliceExpr); if ok && s.Low==nil && s.High==nil && s.Max==nil && !s.Slice3 { out=append(out,Diag{Pos:s.Pos(),Message:fmt.Sprintf("could simplify %s to %s", exprString(ctx,s), exprString(ctx,s.X))}) }; return true }); return out }

func checkValSwap(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool { b,ok:=n.(*ast.BlockStmt); if !ok {return true}; for i:=0; i+2<len(b.List); i++ { a1,ok1:=b.List[i].(*ast.AssignStmt); a2,ok2:=b.List[i+1].(*ast.AssignStmt); a3,ok3:=b.List[i+2].(*ast.AssignStmt); if !ok1||!ok2||!ok3||a1.Tok!=token.DEFINE||a2.Tok!=token.ASSIGN||a3.Tok!=token.ASSIGN||len(a1.Lhs)!=1||len(a1.Rhs)!=1||len(a2.Lhs)!=1||len(a2.Rhs)!=1||len(a3.Lhs)!=1||len(a3.Rhs)!=1 {continue}; tmp:=exprString(ctx,a1.Lhs[0]); x:=exprString(ctx,a1.Rhs[0]); if exprString(ctx,a2.Lhs[0])!=x {continue}; y:=exprString(ctx,a2.Rhs[0]); if exprString(ctx,a3.Lhs[0])==y && exprString(ctx,a3.Rhs[0])==tmp { out=append(out,Diag{Pos:a1.Pos(),Message:fmt.Sprintf("can re-write as `%s, %s = %s, %s`", x,y,y,x)}) } }; return true })
    return out
}

func checkWrapperFunc(ctx *Context) []Diag { var out []Diag; walkFiles(ctx, func(n ast.Node) bool { c,ok:=n.(*ast.CallExpr); if !ok || len(c.Args)!=1 {return true}; se,ok:=c.Fun.(*ast.SelectorExpr); if ok && se.Sel.Name=="Add" { if u,ok:=c.Args[0].(*ast.UnaryExpr); ok && u.Op==token.SUB && isIntLit(u.X,"1") { out=append(out,Diag{Pos:c.Pos(),Message:fmt.Sprintf("use WaitGroup.Done method in `%s`", exprString(ctx,c))}) } }; return true }); return out }

func checkYodaStyleExpr(ctx *Context) []Diag { var out []Diag; walkFiles(ctx, func(n ast.Node) bool { be,ok:=n.(*ast.BinaryExpr); if !ok {return true}; if isConstLike(be.X) && !isConstLike(be.Y) { out=append(out,Diag{Pos:be.Pos(),Message:fmt.Sprintf("consider to replace `%s` with `%s %s %s`", exprString(ctx,be), exprString(ctx,be.Y), be.Op.String(), exprString(ctx,be.X))}) }; return true }); return out }
func isConstLike(e ast.Expr) bool { if _,ok:=e.(*ast.BasicLit); ok {return true}; if isIdent(e,"nil") || isIdent(e,"true") || isIdent(e,"false") {return true}; return false }

func checkZeroByteRepeat(ctx *Context) []Diag { var out []Diag; walkFiles(ctx, func(n ast.Node) bool { c,ok:=n.(*ast.CallExpr); if !ok || !isCallTo(c,"bytes","Repeat") || len(c.Args)!=2 {return true}; if cl,ok:=c.Args[0].(*ast.CompositeLit); ok { if at,ok:=cl.Type.(*ast.ArrayType); ok { if id,ok:=at.Elt.(*ast.Ident); ok && id.Name=="byte" && len(cl.Elts)==1 && isIntLit(cl.Elts[0],"0") { out=append(out,Diag{Pos:c.Pos(),Message:fmt.Sprintf("can replace %s with make([]byte, %s)", exprString(ctx,c), exprString(ctx,c.Args[1]))}) } } }; return true }); return out }

EOF

gofmt -w main.go docs_generated.go
sed -n '1,80p' main.go"}

actions.command:
cat > main.go <<'EOF'
package main

import (
    "bytes"
    "flag"
    "fmt"
    "go/ast"
    "go/importer"
    "go/parser"
    "go/printer"
    "go/token"
    "go/types"
    "io/fs"
    "os"
    "path/filepath"
    "regexp"
    "runtime"
    "sort"
    "strconv"
    "strings"
    "unicode"
)

const version = "v0.0.0-SNAPSHOT"

const defaultEnable = "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc"

type CheckerInfo struct {
    Name string
    Tags []string
}

type Options struct {
    captLocalParamsOnly bool
    elseifSkipBalanced bool
    ifElseChainMinThreshold int
    checkGenerated bool
    checkTests bool
    exitCode int
    verbose bool
}

type FileData struct {
    Path string
    Display string
    Src []byte
    Ast *ast.File
}

type Context struct {
    Fset *token.FileSet
    Files []*FileData
    Info *types.Info
    Opt Options
}

type Diag struct {
    Pos token.Pos
    Message string
}

type checkerFunc func(*Context) []Diag

func main() {
    if len(os.Args) < 2 {
        fmt.Fprintln(os.Stderr, "no args provided")
        return
    }
    switch os.Args[1] {
    case "help":
        printTopHelp()
    case "version":
        fmt.Printf("go-critic version: %s\n", version)
    case "doc":
        os.Exit(runDoc(os.Args[2:]))
    case "check":
        os.Exit(runCheck(os.Args[2:]))
    default:
        cmd := os.Args[1]
        if sug := suggestCommand(cmd); sug != "" {
            fmt.Fprintf(os.Stdout, "%q unknown command, did you mean %q?\n", cmd, sug)
        } else {
            fmt.Fprintf(os.Stdout, "%q unknown command\n", cmd)
        }
        fmt.Fprintln(os.Stdout, "Run \"go-critic help\" for usage.")
        fmt.Fprintf(os.Stderr, "no such command %q\n", cmd)
    }
}

func printTopHelp() {
    fmt.Printf("Usage:\n\n"+
        "    go-critic <command> [arguments...]\n\n"+
        "The commands are:\n\n"+
        "    check             run linter over specified targets\n"+
        "    doc               get installed checkers documentation\n"+
        "    help              shows help message\n"+
        "    version           shows version of the application\n\n"+
        "Version: %s\n", version)
}

func suggestCommand(cmd string) string {
    commands := []string{"check", "doc", "help", "version"}
    best := ""
    bestDist := 99
    for _, c := range commands {
        d := levenshtein(cmd, c)
        if d < bestDist {
            bestDist = d
            best = c
        }
    }
    if bestDist <= 2 {
        return best
    }
    return ""
}

func levenshtein(a, b string) int {
    ar, br := []rune(a), []rune(b)
    dp := make([]int, len(br)+1)
    for j := range dp { dp[j] = j }
    for i := 1; i <= len(ar); i++ {
        prev := dp[0]
        dp[0] = i
        for j := 1; j <= len(br); j++ {
            old := dp[j]
            cost := 0
            if ar[i-1] != br[j-1] { cost = 1 }
            dp[j] = min3(dp[j]+1, dp[j-1]+1, prev+cost)
            prev = old
        }
    }
    return dp[len(br)]
}
func min3(a,b,c int) int { if a<b { if a<c {return a}; return c }; if b<c {return b}; return c }

func runDoc(args []string) int {
    fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    if err := fs.Parse(args); err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 0
    }
    rest := fs.Args()
    if len(rest) > 1 {
        fmt.Fprintln(os.Stderr, "expected 0 or 1 positional arguments")
        return 1
    }
    if len(rest) == 0 {
        fmt.Print(checkerListOutput)
        return 0
    }
    name := rest[0]
    doc, ok := checkerDocs[name]
    if !ok {
        fmt.Fprintf(os.Stderr, "checker with name %q not found\n", name)
        return 1
    }
    fmt.Print(doc)
    return 0
}

func runCheck(args []string) int {
    var opt Options
    var enable, disable string
    var enableAll bool
    fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    fs.BoolVar(&opt.captLocalParamsOnly, "@captLocal.paramsOnly", true, "whether to restrict checker to params only")
    fs.Int("@commentedOutCode.minLength", 15, "min length of the comment that triggers a warning")
    fs.BoolVar(&opt.elseifSkipBalanced, "@elseif.skipBalanced", true, "whether to skip balanced if-else pairs")
    fs.Int("@hugeParam.sizeThreshold", 80, "size in bytes that makes the warning trigger")
    fs.IntVar(&opt.ifElseChainMinThreshold, "@ifElseChain.minThreshold", 2, "min number of if-else blocks that makes the warning trigger")
    fs.Int("@nestingReduce.bodyWidth", 5, "min number of statements inside a branch to trigger a warning")
    fs.Int("@rangeExprCopy.sizeThreshold", 512, "size in bytes that makes the warning trigger")
    fs.Bool("@rangeExprCopy.skipTestFuncs", true, "whether to check test functions")
    fs.Int("@rangeValCopy.sizeThreshold", 128, "size in bytes that makes the warning trigger")
    fs.Bool("@rangeValCopy.skipTestFuncs", true, "whether to check test functions")
    fs.String("@ruleguard.debug", "", "enable debug for the specified named rules group")
    fs.String("@ruleguard.disable", "", "comma-separated list of disabled groups or skip empty to enable everything")
    fs.String("@ruleguard.enable", "<all>", "comma-separated list of enabled groups or skip empty to enable everything")
    fs.String("@ruleguard.failOn", "", "Determines the behavior when an error occurs while parsing ruleguard files.\n\tIf flag is not set, log error and skip rule files that contain an error.\n\tIf flag is set, the value must be a comma-separated list of error conditions.\n\t* 'import': rule refers to a package that cannot be loaded.\n\t* 'dsl':    gorule file does not comply with the ruleguard DSL.")
    fs.Bool("@ruleguard.failOnError", false, "deprecated, use failOn param; if set to true, identical to failOn='all', otherwise failOn=''")
    fs.String("@ruleguard.rules", "", "comma-separated list of gorule file paths. Glob patterns such as 'rules-*.go' may be specified")
    fs.Int("@tooManyResultsChecker.maxResults", 5, "maximum number of results")
    fs.Bool("@truncateCmp.skipArchDependent", true, "whether to skip int/uint/uintptr types")
    fs.Bool("@underef.skipRecvDeref", true, "whether to skip (*x).method() calls where x is a pointer receiver")
    fs.Bool("@unnamedResult.checkExported", false, "whether to check exported functions")
    fs.BoolVar(&opt.checkGenerated, "checkGenerated", false, "whether to check generated files")
    fs.BoolVar(&opt.checkTests, "checkTests", true, "whether to check test files")
    fs.Int("concurrency", runtime.GOMAXPROCS(0), "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
    fs.String("cpuprofile", "", "write CPU profile to the specified file")
    fs.StringVar(&disable, "disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
    fs.StringVar(&enable, "enable", defaultEnable, "comma-separated list of enabled checkers. Can include #tags")
    fs.BoolVar(&enableAll, "enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
    fs.IntVar(&opt.exitCode, "exitCode", 1, "exit code to be used when lint issues are found")
    fs.String("go", "", "select the Go version to target. Leave as string for the latest")
    fs.String("memprofile", "", "write memory profile to the specified file")
    fs.Bool("shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
    fs.BoolVar(&opt.verbose, "v", false, "whether to print output useful during linter debugging")
    if err := fs.Parse(args); err != nil {
        fmt.Fprintln(os.Stderr, "parse args:", err)
        return 1
    }

    selected, reasons := selectCheckers(enable, disable, enableAll)
    if opt.verbose {
        for _, info := range checkerInfos {
            if !selected[info.Name] {
                reason := reasons[info.Name]
                if reason == "" { reason = "not enabled by name or tag (-enable)" }
                fmt.Fprintf(os.Stderr, "\tdebug: %s: %s\n", info.Name, reason)
            }
        }
        for _, info := range checkerInfos {
            if selected[info.Name] {
                fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", info.Name)
            }
        }
    }
    if len(selected) == 0 {
        fmt.Fprintln(os.Stderr, "init checkers: empty checkers set selected")
        return 1
    }

    files := loadTargets(fs.Args(), opt)
    if len(files) == 0 {
        return 0
    }
    if opt.verbose {
        fmt.Fprintf(os.Stderr, "\tdebug: checking %q package (%d files)\n", packageNameForVerbose(files), len(files))
    }
    ctx := buildContext(files, opt)
    any := false
    funcs := checkerFuncs()
    for _, info := range checkerInfos {
        if !selected[info.Name] { continue }
        fn := funcs[info.Name]
        if fn == nil { continue }
        diags := fn(ctx)
        if len(diags) == 0 { continue }
        any = true
        if info.Name == "assignOp" {
            sort.SliceStable(diags, func(i,j int) bool {
                if diags[i].Message != diags[j].Message { return diags[i].Message < diags[j].Message }
                return ctx.Fset.Position(diags[i].Pos).Offset < ctx.Fset.Position(diags[j].Pos).Offset
            })
        }
        for _, d := range diags {
            pos := ctx.Fset.Position(d.Pos)
            fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", displayPath(pos.Filename), pos.Line, pos.Column, info.Name, d.Message)
        }
    }
    if any { return opt.exitCode }
    return 0
}

func selectCheckers(enable, disable string, enableAll bool) (map[string]bool, map[string]string) {
    selected := map[string]bool{}
    reasons := map[string]string{}
    if enableAll {
        for _, info := range checkerInfos { selected[info.Name] = true }
    } else {
        for _, tok := range splitCSV(enable) {
            for _, name := range expandCheckerSelector(tok) { selected[name] = true }
        }
    }
    for _, tok := range splitCSV(disable) {
        if tok == "" { continue }
        names := expandCheckerSelector(tok)
        for _, name := range names {
            if selected[name] {
                delete(selected, name)
                if strings.HasPrefix(tok, "#") { reasons[name] = "disabled by tag (-disable)" } else { reasons[name] = "disabled by name (-disable)" }
            }
        }
    }
    return selected, reasons
}

func splitCSV(s string) []string {
    if s == "" { return nil }
    parts := strings.Split(s, ",")
    out := make([]string, 0, len(parts))
    for _, p := range parts { out = append(out, strings.TrimSpace(p)) }
    return out
}

func expandCheckerSelector(sel string) []string {
    if sel == "" { return nil }
    var out []string
    if strings.HasPrefix(sel, "#") {
        tag := strings.TrimPrefix(sel, "#")
        for _, info := range checkerInfos {
            for _, t := range info.Tags { if t == tag { out = append(out, info.Name); break } }
        }
        return out
    }
    for _, info := range checkerInfos { if info.Name == sel { return []string{sel} } }
    return nil
}

func loadTargets(args []string, opt Options) []*FileData {
    var paths []string
    seen := map[string]bool{}
    add := func(p string) {
        abs, err := filepath.Abs(p); if err != nil { return }
        if seen[abs] { return }
        seen[abs] = true
        paths = append(paths, abs)
    }
    for _, arg := range args {
        if strings.HasSuffix(arg, ".go") {
            if st, err := os.Stat(arg); err == nil && !st.IsDir() { add(arg) }
            continue
        }
        if strings.HasSuffix(arg, "/...") || arg == "./..." || arg == "..." {
            base := strings.TrimSuffix(arg, "/...")
            if base == "" || base == "." { base = "." }
            filepath.WalkDir(base, func(path string, d fs.DirEntry, err error) error {
                if err != nil { return nil }
                if d.IsDir() {
                    name := d.Name()
                    if name == ".git" || name == "vendor" { return filepath.SkipDir }
                    return nil
                }
                if strings.HasSuffix(path, ".go") { add(path) }
                return nil
            })
            continue
        }
        if st, err := os.Stat(arg); err == nil && st.IsDir() {
            entries, _ := os.ReadDir(arg)
            for _, e := range entries {
                if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") { add(filepath.Join(arg, e.Name())) }
            }
            continue
        }
    }
    sort.Strings(paths)
    fset := token.NewFileSet()
    _ = fset
    var files []*FileData
    for _, path := range paths {
        if !opt.checkTests && strings.HasSuffix(path, "_test.go") { continue }
        src, err := os.ReadFile(path); if err != nil { continue }
        // Parse later in buildContext; use a temporary parser here only for generated-file filtering.
        tfset := token.NewFileSet()
        af, err := parser.ParseFile(tfset, path, src, parser.ParseComments)
        if err != nil { continue }
        if !opt.checkGenerated && isGeneratedFile(af) { continue }
        files = append(files, &FileData{Path:path, Display:displayPath(path), Src:src})
    }
    return files
}

func buildContext(files []*FileData, opt Options) *Context {
    fset := token.NewFileSet()
    parsed := files[:0]
    for _, fd := range files {
        af, err := parser.ParseFile(fset, fd.Path, fd.Src, parser.ParseComments)
        if err != nil { continue }
        fd.Ast = af
        parsed = append(parsed, fd)
    }
    info := &types.Info{
        Types: map[ast.Expr]types.TypeAndValue{},
        Defs: map[*ast.Ident]types.Object{},
        Uses: map[*ast.Ident]types.Object{},
        Selections: map[*ast.SelectorExpr]*types.Selection{},
    }
    groups := map[string][]*ast.File{}
    for _, fd := range parsed { groups[fd.Ast.Name.Name] = append(groups[fd.Ast.Name.Name], fd.Ast) }
    conf := types.Config{Importer: importer.Default(), Error: func(error){}}
    for pkg, fs := range groups {
        _, _ = conf.Check(pkg, fset, fs, info)
    }
    return &Context{Fset:fset, Files:parsed, Info:info, Opt:opt}
}

func isGeneratedFile(f *ast.File) bool {
    for _, cg := range f.Comments {
        if cg.Pos() > f.Package { break }
        for _, c := range cg.List {
            text := strings.TrimSpace(c.Text)
            if regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`).MatchString(text) { return true }
        }
    }
    return false
}

func packageNameForVerbose(files []*FileData) string {
    // File targets in the original are reported as command-line-arguments.  For module dirs,
    // derive a small approximation from go.mod when possible.
    cwd, _ := os.Getwd()
    if mod := findModulePath(cwd); mod != "" { return mod }
    return "command-line-arguments"
}
func findModulePath(dir string) string {
    for {
        data, err := os.ReadFile(filepath.Join(dir, "go.mod")); if err == nil {
            for _, line := range strings.Split(string(data), "\n") {
                line = strings.TrimSpace(line)
                if strings.HasPrefix(line, "module ") { return strings.TrimSpace(strings.TrimPrefix(line, "module ")) }
            }
        }
        parent := filepath.Dir(dir); if parent == dir { return "" }; dir = parent
    }
}

func displayPath(path string) string {
    if path == "" { return path }
    abs, err := filepath.Abs(path); if err != nil { return filepath.ToSlash(path) }
    cwd, _ := os.Getwd()
    if rel, err := filepath.Rel(cwd, abs); err == nil && rel != "." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != ".." {
        return "./" + filepath.ToSlash(rel)
    }
    return filepath.ToSlash(abs)
}

func checkerFuncs() map[string]checkerFunc {
    return map[string]checkerFunc{
        "appendAssign": checkAppendAssign,
        "appendCombine": checkAppendCombine,
        "argOrder": checkArgOrder,
        "assignOp": checkAssignOp,
        "badCall": checkBadCall,
        "badCond": checkBadCond,
        "boolExprSimplify": checkBoolExprSimplify,
        "captLocal": checkCaptLocal,
        "caseOrder": checkCaseOrder,
        "codegenComment": checkCodegenComment,
        "commentFormatting": checkCommentFormatting,
        "defaultCaseOrder": checkDefaultCaseOrder,
        "deprecatedComment": checkDeprecatedComment,
        "deferUnlambda": checkDeferUnlambda,
        "dupArg": checkDupArg,
        "dupBranchBody": checkDupBranchBody,
        "dupCase": checkDupCase,
        "dupSubExpr": checkDupSubExpr,
        "elseif": checkElseIf,
        "emptyStringTest": checkEmptyStringTest,
        "exitAfterDefer": checkExitAfterDefer,
        "flagDeref": checkFlagDeref,
        "flagName": checkFlagName,
        "hexLiteral": checkHexLiteral,
        "httpNoBody": checkHTTPNoBody,
        "ifElseChain": checkIfElseChain,
        "mapKey": checkMapKey,
        "newDeref": checkNewDeref,
        "octalLiteral": checkOctalLiteral,
        "offBy1": checkOffBy1,
        "paramTypeCombine": checkParamTypeCombine,
        "preferDecodeRune": checkPreferDecodeRune,
        "preferStringWriter": checkPreferStringWriter,
        "preferWriteByte": checkPreferWriteByte,
        "regexpMust": checkRegexpMust,
        "singleCaseSwitch": checkSingleCaseSwitch,
        "sloppyLen": checkSloppyLen,
        "sloppyTypeAssert": checkSloppyTypeAssert,
        "stringXbytes": checkStringXbytes,
        "stringsCompare": checkStringsCompare,
        "switchTrue": checkSwitchTrue,
        "typeSwitchVar": checkTypeSwitchVar,
        "underef": checkUnderef,
        "unlambda": checkUnlambda,
        "unnecessaryBlock": checkUnnecessaryBlock,
        "unnecessaryDefer": checkUnnecessaryDefer,
        "unslice": checkUnslice,
        "valSwap": checkValSwap,
        "wrapperFunc": checkWrapperFunc,
        "yodaStyleExpr": checkYodaStyleExpr,
        "zeroByteRepeat": checkZeroByteRepeat,
    }
}

func walkFiles(ctx *Context, fn func(ast.Node) bool) {
    for _, fd := range ctx.Files { ast.Inspect(fd.Ast, fn) }
}

func nodeString(fset *token.FileSet, n any) string {
    var b bytes.Buffer
    _ = printer.Fprint(&b, fset, n)
    return b.String()
}
func exprString(ctx *Context, n ast.Node) string { return nodeString(ctx.Fset, n) }

func isIdent(e ast.Expr, name string) bool { id, ok := e.(*ast.Ident); return ok && id.Name == name }
func isIntLit(e ast.Expr, val string) bool { lit, ok := e.(*ast.BasicLit); return ok && lit.Kind == token.INT && lit.Value == val }
func isStringLit(e ast.Expr) (string, bool) { lit, ok := e.(*ast.BasicLit); if !ok || lit.Kind != token.STRING { return "", false }; s, err := strconv.Unquote(lit.Value); return s, err == nil }
func selectorName(e ast.Expr) (x, sel string, ok bool) { se, ok := e.(*ast.SelectorExpr); if !ok { return "","",false }; return nodeString(token.NewFileSet(), se.X), se.Sel.Name, true }
func callName(c *ast.CallExpr) string { return nodeString(token.NewFileSet(), c.Fun) }

func isCallTo(c *ast.CallExpr, pkg, name string) bool {
    se, ok := c.Fun.(*ast.SelectorExpr); if !ok { return false }
    id, ok := se.X.(*ast.Ident); return ok && id.Name == pkg && se.Sel.Name == name
}
func isBuiltinCall(c *ast.CallExpr, name string) bool { id, ok := c.Fun.(*ast.Ident); return ok && id.Name == name }

func checkAppendAssign(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        as, ok := n.(*ast.AssignStmt); if !ok || len(as.Lhs) != 1 || len(as.Rhs) != 1 { return true }
        call, ok := as.Rhs[0].(*ast.CallExpr); if !ok || !isBuiltinCall(call, "append") || len(call.Args) == 0 { return true }
        if exprString(ctx, as.Lhs[0]) != exprString(ctx, call.Args[0]) {
            out = append(out, Diag{Pos: call.Pos(), Message: "append result not assigned to the same slice"})
        }
        return true
    })
    return out
}

func checkAppendCombine(ctx *Context) []Diag {
    var out []Diag
    for _, fd := range ctx.Files {
        ast.Inspect(fd.Ast, func(n ast.Node) bool {
            block, ok := n.(*ast.BlockStmt); if !ok { return true }
            for i := 0; i+1 < len(block.List); i++ {
                a1, ok1 := appendAssignParts(block.List[i], ctx)
                a2, ok2 := appendAssignParts(block.List[i+1], ctx)
                if ok1 && ok2 && a1 == a2 {
                    out = append(out, Diag{Pos: block.List[i].Pos(), Message: fmt.Sprintf("can combine chain of append calls into one append")})
                }
            }
            return true
        })
    }
    return out
}
func appendAssignParts(s ast.Stmt, ctx *Context) (string,bool) { as,ok:=s.(*ast.AssignStmt); if !ok || len(as.Lhs)!=1 || len(as.Rhs)!=1 {return "",false}; call,ok:=as.Rhs[0].(*ast.CallExpr); if !ok || !isBuiltinCall(call,"append") || len(call.Args)==0 {return "",false}; lhs:=exprString(ctx,as.Lhs[0]); if lhs==exprString(ctx,call.Args[0]) {return lhs,true}; return "",false }

func checkArgOrder(ctx *Context) []Diag {
    names := map[string]bool{"HasPrefix":true,"HasSuffix":true,"Contains":true,"ContainsAny":true,"ContainsRune":true}
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        c, ok := n.(*ast.CallExpr); if !ok || len(c.Args) < 2 { return true }
        se, ok := c.Fun.(*ast.SelectorExpr); if !ok || !names[se.Sel.Name] { return true }
        if id, ok := se.X.(*ast.Ident); !ok || id.Name != "strings" { return true }
        if _, ok := c.Args[0].(*ast.BasicLit); ok {
            if _, ok2 := c.Args[1].(*ast.BasicLit); !ok2 {
                out = append(out, Diag{Pos:c.Pos(), Message:fmt.Sprintf("%s and %s arguments order looks reversed", exprString(ctx,c.Args[0]), exprString(ctx,c.Args[1]))})
            }
        }
        return true
    })
    return out
}

func checkAssignOp(ctx *Context) []Diag {
    ops := map[token.Token]string{token.ADD:"+", token.SUB:"-", token.MUL:"*", token.QUO:"/", token.REM:"%", token.SHL:"<<", token.SHR:">>", token.AND:"&", token.OR:"|", token.XOR:"^", token.AND_NOT:"&^"}
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        as, ok := n.(*ast.AssignStmt); if !ok || as.Tok != token.ASSIGN || len(as.Lhs) != 1 || len(as.Rhs) != 1 { return true }
        be, ok := as.Rhs[0].(*ast.BinaryExpr); if !ok { return true }
        op, ok := ops[be.Op]; if !ok { return true }
        lhs := exprString(ctx, as.Lhs[0])
        if exprString(ctx, be.X) != lhs { return true }
        rhs := exprString(ctx, be.Y)
        replacement := fmt.Sprintf("%s %s= %s", lhs, op, rhs)
        if be.Op == token.ADD && isIntLit(be.Y, "1") { replacement = lhs + "++" }
        if be.Op == token.SUB && isIntLit(be.Y, "1") { replacement = lhs + "--" }
        msg := fmt.Sprintf("replace `%s` with `%s`", exprString(ctx, as), replacement)
        out = append(out, Diag{Pos:as.Pos(), Message:msg})
        return true
    })
    return out
}

func checkBadCall(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        c, ok := n.(*ast.CallExpr); if !ok { return true }
        if isCallTo(c, "strings", "Replace") && len(c.Args) == 4 && isIntLit(c.Args[3], "0") {
            out = append(out, Diag{Pos:c.Args[3].Pos(), Message:"suspicious arg 0, probably meant -1"})
        }
        return true
    })
    return out
}

func checkBadCond(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        fs, ok := n.(*ast.ForStmt); if !ok || fs.Cond == nil || fs.Post == nil { return true }
        be, ok := fs.Cond.(*ast.BinaryExpr); if !ok { return true }
        post, ok := fs.Post.(*ast.IncDecStmt); if !ok { return true }
        id, ok := be.X.(*ast.Ident); if !ok { return true }
        if !isIdent(post.X, id.Name) { return true }
        if post.Tok == token.INC && (be.Op == token.GTR || be.Op == token.GEQ) {
            repl := "<"; if be.Op == token.GEQ { repl = "<=" }
            out = append(out, Diag{Pos:fs.Pos(), Message:fmt.Sprintf("`%s` in loop; probably meant `%s %s %s`?", exprString(ctx, be), id.Name, repl, exprString(ctx, be.Y))})
        } else if post.Tok == token.DEC && (be.Op == token.LSS || be.Op == token.LEQ) {
            repl := ">"; if be.Op == token.LEQ { repl = ">=" }
            out = append(out, Diag{Pos:fs.Pos(), Message:fmt.Sprintf("`%s` in loop; probably meant `%s %s %s`?", exprString(ctx, be), id.Name, repl, exprString(ctx, be.Y))})
        }
        return true
    })
    return out
}

func checkBoolExprSimplify(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        u, ok := n.(*ast.UnaryExpr); if !ok || u.Op != token.NOT { return true }
        if p, ok := u.X.(*ast.ParenExpr); ok {
            if be, ok := p.X.(*ast.BinaryExpr); ok {
                neg := map[token.Token]string{token.GEQ:"<", token.LEQ:">", token.GTR:"<=", token.LSS:">=", token.EQL:"!=", token.NEQ:"=="}
                if op, ok := neg[be.Op]; ok {
                    out = append(out, Diag{Pos:u.Pos(), Message:fmt.Sprintf("could simplify %s to %s %s %s", exprString(ctx,u), exprString(ctx,be.X), op, exprString(ctx,be.Y))})
                }
            }
        }
        return true
    })
    return out
}

func checkCaptLocal(ctx *Context) []Diag {
    var out []Diag
    checkName := func(id *ast.Ident) { if id == nil || id.Name == "_" { return }; r, _ := utf8First(id.Name); if unicode.IsUpper(r) { out = append(out, Diag{Pos:id.Pos(), Message:fmt.Sprintf("`%s' should not be capitalized", id.Name)}) } }
    for _, fd := range ctx.Files {
        ast.Inspect(fd.Ast, func(n ast.Node) bool {
            switch x := n.(type) {
            case *ast.FuncDecl:
                if x.Type.Params != nil { for _, f := range x.Type.Params.List { for _, id := range f.Names { checkName(id) } } }
                if x.Type.Results != nil { for _, f := range x.Type.Results.List { for _, id := range f.Names { checkName(id) } } }
            case *ast.FuncLit:
                if x.Type.Params != nil { for _, f := range x.Type.Params.List { for _, id := range f.Names { checkName(id) } } }
                if x.Type.Results != nil { for _, f := range x.Type.Results.List { for _, id := range f.Names { checkName(id) } } }
            case *ast.AssignStmt:
                if !ctx.Opt.captLocalParamsOnly && x.Tok == token.DEFINE { for _, e := range x.Lhs { if id, ok := e.(*ast.Ident); ok { checkName(id) } } }
            case *ast.ValueSpec:
                if !ctx.Opt.captLocalParamsOnly { for _, id := range x.Names { checkName(id) } }
            }
            return true
        })
    }
    return out
}
func utf8First(s string) (rune,int) { for i,r := range s { return r,i }; return 0,0 }

func checkCaseOrder(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        ts, ok := n.(*ast.TypeSwitchStmt); if !ok { return true }
        var prevExprs []ast.Expr
        for _, st := range ts.Body.List {
            cc := st.(*ast.CaseClause)
            for _, cur := range cc.List {
                ct := ctx.Info.Types[cur].Type
                for _, prev := range prevExprs {
                    pt := ctx.Info.Types[prev].Type
                    if ct != nil && pt != nil && !types.Identical(ct, pt) && types.AssignableTo(ct, pt) {
                        out = append(out, Diag{Pos:cc.Pos(), Message:fmt.Sprintf("case %s must go before the %s case", exprString(ctx,cur), exprString(ctx,prev))})
                        break
                    }
                }
            }
            prevExprs = append(prevExprs, cc.List...)
        }
        return true
    })
    return out
}

func checkCodegenComment(ctx *Context) []Diag {
    valid := regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)
    var out []Diag
    for _, fd := range ctx.Files {
        for _, cg := range fd.Ast.Comments {
            if cg.Pos() > fd.Ast.Package { break }
            for _, c := range cg.List {
                text := strings.TrimSpace(c.Text)
                low := strings.ToLower(text)
                if strings.Contains(low, "generated") && !valid.MatchString(text) {
                    out = append(out, Diag{Pos:c.Pos(), Message:"comment should match `Code generated .* DO NOT EDIT.` regexp"})
                }
            }
        }
    }
    return out
}

func checkCommentFormatting(ctx *Context) []Diag {
    var out []Diag
    for _, fd := range ctx.Files {
        for _, cg := range fd.Ast.Comments {
            for _, c := range cg.List {
                t := c.Text
                if !strings.HasPrefix(t, "//") || len(t) < 3 { continue }
                rest := t[2:]
                if rest == "" || strings.HasPrefix(rest, " ") || strings.HasPrefix(rest, "\t") || strings.HasPrefix(rest, "/") { continue }
                lower := strings.ToLower(rest)
                skipPrefixes := []string{"go:", "line ", "extern ", "export ", "sys ", "nolint", "lint:", "+build", "go:build"}
                skip := false
                for _, p := range skipPrefixes { if strings.HasPrefix(lower, p) { skip = true; break } }
                if skip { continue }
                out = append(out, Diag{Pos:c.Pos(), Message:"put a space between `//` and comment text"})
            }
        }
    }
    return out
}

func checkDefaultCaseOrder(ctx *Context) []Diag {
    var out []Diag
    checkList := func(list []ast.Stmt) {
        for i, st := range list {
            if cc, ok := st.(*ast.CaseClause); ok && cc.List == nil && i != 0 && i != len(list)-1 {
                out = append(out, Diag{Pos:cc.Pos(), Message:"consider to make `default` case as first or as last case"})
            }
        }
    }
    walkFiles(ctx, func(n ast.Node) bool { switch x:=n.(type){case *ast.SwitchStmt: checkList(x.Body.List); case *ast.TypeSwitchStmt: checkList(x.Body.List)}; return true })
    return out
}

func checkDeprecatedComment(ctx *Context) []Diag {
    var out []Diag
    checkGroup := func(cg *ast.CommentGroup) {
        if cg == nil { return }
        for _, c := range cg.List {
            text := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
            text = strings.TrimSpace(strings.TrimPrefix(text, "/*"))
            if strings.HasPrefix(text, "Deprecated ") && !strings.HasPrefix(text, "Deprecated: ") {
                out = append(out, Diag{Pos:c.Pos(), Message:"the proper format is `Deprecated: <text>`"})
            } else if strings.HasPrefix(text, "deprecated: ") {
                out = append(out, Diag{Pos:c.Pos(), Message:"use `Deprecated: ` (note the casing) instead of `deprecated: `"})
            }
        }
    }
    for _, fd := range ctx.Files {
        for _, decl := range fd.Ast.Decls {
            switch d := decl.(type) { case *ast.FuncDecl: checkGroup(d.Doc); case *ast.GenDecl: checkGroup(d.Doc); for _, sp := range d.Specs { switch s:=sp.(type){case *ast.TypeSpec: checkGroup(s.Doc); case *ast.ValueSpec: checkGroup(s.Doc)} } }
        }
    }
    return out
}

func checkDeferUnlambda(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        d, ok := n.(*ast.DeferStmt); if !ok { return true }
        c := d.Call
        fl, ok := c.Fun.(*ast.FuncLit); if !ok || len(c.Args) != 0 || len(fl.Body.List) != 1 { return true }
        es, ok := fl.Body.List[0].(*ast.ExprStmt); if !ok { return true }
        inner, ok := es.X.(*ast.CallExpr); if !ok || len(inner.Args) != 0 { return true }
        out = append(out, Diag{Pos:d.Pos(), Message:fmt.Sprintf("can replace `%s` with `%s()`", exprString(ctx,d), exprString(ctx,inner.Fun))})
        return true
    })
    return out
}

func checkDupArg(ctx *Context) []Diag {
    var out []Diag
    suspicious := map[string]bool{"copy":true,"append":false,"bytes.Equal":true,"bytes.Compare":true,"strings.Compare":true,"reflect.DeepEqual":true}
    walkFiles(ctx, func(n ast.Node) bool {
        c, ok := n.(*ast.CallExpr); if !ok || len(c.Args) < 2 { return true }
        name := exprString(ctx,c.Fun)
        if !suspicious[name] { return true }
        if exprString(ctx,c.Args[0]) == exprString(ctx,c.Args[1]) {
            out = append(out, Diag{Pos:c.Pos(), Message:fmt.Sprintf("suspicious duplicated args in %s", exprString(ctx,c))})
        }
        return true
    })
    return out
}

func checkDupBranchBody(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        is, ok := n.(*ast.IfStmt); if !ok || is.Else == nil { return true }
        eb, ok := is.Else.(*ast.BlockStmt); if !ok { return true }
        if strings.TrimSpace(exprString(ctx,is.Body)) == strings.TrimSpace(exprString(ctx,eb)) {
            out = append(out, Diag{Pos:is.Pos(), Message:"both branches in if statement have same body"})
        }
        return true
    })
    return out
}

func checkDupCase(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        switch sw := n.(type) {
        case *ast.SwitchStmt:
            seen := map[string]bool{}
            for _, st := range sw.Body.List { cc:=st.(*ast.CaseClause); for _, e := range cc.List { key:=exprString(ctx,e); if seen[key] { out=append(out,Diag{Pos:e.Pos(),Message:fmt.Sprintf("'case %s' is duplicated", key)}) }; seen[key]=true } }
        case *ast.TypeSwitchStmt:
            seen := map[string]bool{}
            for _, st := range sw.Body.List { cc:=st.(*ast.CaseClause); for _, e := range cc.List { key:=exprString(ctx,e); if seen[key] { out=append(out,Diag{Pos:e.Pos(),Message:fmt.Sprintf("'case %s' is duplicated", key)}) }; seen[key]=true } }
        case *ast.SelectStmt:
            seen := map[string]bool{}
            for _, st := range sw.Body.List { cc:=st.(*ast.CommClause); if cc.Comm==nil {continue}; key:=exprString(ctx,cc.Comm); if seen[key] { out=append(out,Diag{Pos:cc.Pos(),Message:fmt.Sprintf("'case %s' is duplicated", key)}) }; seen[key]=true }
        }
        return true
    })
    return out
}

func checkDupSubExpr(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        be, ok := n.(*ast.BinaryExpr); if !ok { return true }
        if exprString(ctx,be.X) == exprString(ctx,be.Y) {
            out = append(out, Diag{Pos:be.Pos(), Message:fmt.Sprintf("suspicious identical LHS and RHS for `%s` operator", be.Op.String())})
        }
        return true
    })
    return out
}

func checkElseIf(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        is, ok := n.(*ast.IfStmt); if !ok { return true }
        eb, ok := is.Else.(*ast.BlockStmt); if !ok || len(eb.List) != 1 { return true }
        if _, ok := eb.List[0].(*ast.IfStmt); ok { out = append(out, Diag{Pos:is.Pos(), Message:"can replace 'else {if cond {}}' with 'else if cond {}'"}) }
        return true
    })
    return out
