func checkEmptyStringTest(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        be, ok := n.(*ast.BinaryExpr); if !ok { return true }
        call, ok := be.X.(*ast.CallExpr); if !ok || !isBuiltinCall(call,"len") || len(call.Args)!=1 { return true }
        if (be.Op == token.EQL || be.Op == token.NEQ) && isIntLit(be.Y,"0") {
            op := "=="; if be.Op == token.NEQ { op = "!=" }
            out = append(out, Diag{Pos:be.Pos(), Message:fmt.Sprintf("replace %s with %s %s \"\"", exprString(ctx,be), exprString(ctx,call.Args[0]), op)})
        }
        return true
    })
    return out
}

func checkExitAfterDefer(ctx *Context) []Diag {
    var out []Diag
    for _, fd := range ctx.Files {
        ast.Inspect(fd.Ast, func(n ast.Node) bool {
            var body *ast.BlockStmt
            switch f := n.(type) { case *ast.FuncDecl: body=f.Body; case *ast.FuncLit: body=f.Body; default: return true }
            if body == nil { return true }
            var deferCall string
            ast.Inspect(body, func(nn ast.Node) bool { if d,ok:=nn.(*ast.DeferStmt); ok && deferCall=="" { deferCall="defer "+exprString(ctx,d.Call) }; return true })
            if deferCall == "" { return true }
            ast.Inspect(body, func(nn ast.Node) bool {
                c, ok := nn.(*ast.CallExpr); if !ok { return true }
                name := exprString(ctx,c.Fun)
                if name == "os.Exit" || strings.HasPrefix(name,"log.Fatal") || strings.HasPrefix(name,"logger.Fatal") {
                    out = append(out, Diag{Pos:c.Pos(), Message:fmt.Sprintf("%s will exit, and `%s` will not run", name, deferCall)})
                }
                return true
            })
            return false
        })
    }
    return out
}

func checkFlagDeref(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        u, ok := n.(*ast.UnaryExpr); if !ok || u.Op != token.MUL { return true }
        c, ok := u.X.(*ast.CallExpr); if !ok { return true }
        se, ok := c.Fun.(*ast.SelectorExpr); if !ok { return true }
        id, ok := se.X.(*ast.Ident); if !ok || id.Name != "flag" || strings.HasSuffix(se.Sel.Name,"Var") { return true }
        out = append(out, Diag{Pos:u.Pos(), Message:fmt.Sprintf("immediate deref in %s is most likely an error; consider using flag.%sVar", exprString(ctx,u), se.Sel.Name)})
        return true
    })
    return out
}

func checkFlagName(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        c, ok := n.(*ast.CallExpr); if !ok { return true }
        se, ok := c.Fun.(*ast.SelectorExpr); if !ok { return true }
        id, ok := se.X.(*ast.Ident); if !ok || id.Name != "flag" { return true }
        idx := 0; if strings.HasSuffix(se.Sel.Name,"Var") { idx = 1 }
        if len(c.Args) <= idx { return true }
        s, ok := isStringLit(c.Args[idx]); if !ok { return true }
        if strings.TrimSpace(s) != s { out = append(out, Diag{Pos:c.Pos(), Message:fmt.Sprintf("flag name %q contains whitespace", s)})
        } else if strings.HasPrefix(s,"-") { out = append(out, Diag{Pos:c.Pos(), Message:fmt.Sprintf("flag name %q should not start with a hyphen", s)}) }
        return true
    })
    return out
}

func checkHexLiteral(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool { lit,ok:=n.(*ast.BasicLit); if !ok || lit.Kind!=token.INT {return true}; v:=lit.Value; if strings.HasPrefix(v,"0X") {out=append(out,Diag{Pos:lit.Pos(),Message:fmt.Sprintf("use 0x prefix instead of 0X in %s", v)})}; if strings.HasPrefix(strings.ToLower(v),"0x") { hasLow,hasUp:=false,false; for _,r:=range v[2:] { if r>='a'&&r<='f'{hasLow=true}; if r>='A'&&r<='F'{hasUp=true} }; if hasLow&&hasUp {out=append(out,Diag{Pos:lit.Pos(),Message:fmt.Sprintf("use consistent digits case in %s", v)})} }; return true })
    return out
}

func checkHTTPNoBody(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool { c,ok:=n.(*ast.CallExpr); if !ok || len(c.Args)<3 {return true}; if (isCallTo(c,"http","NewRequest")||isCallTo(c,"http","NewRequestWithContext")) && isIdent(c.Args[len(c.Args)-1],"nil") { out=append(out,Diag{Pos:c.Args[len(c.Args)-1].Pos(),Message:"use http.NoBody instead of nil in http.NewRequest"}) }; return true })
    return out
}

func checkIfElseChain(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        is, ok := n.(*ast.IfStmt); if !ok || is.Else == nil { return true }
        if isPartOfElseIf(ctx, is) { return true }
        count := 0
        cur := is
        for cur.Else != nil {
            switch e := cur.Else.(type) {
            case *ast.IfStmt: count++; cur = e
            case *ast.BlockStmt: count++; cur = nil
            default: cur = nil
            }
            if cur == nil { break }
        }
        if count >= ctx.Opt.ifElseChainMinThreshold { out = append(out, Diag{Pos:is.Pos(), Message:"rewrite if-else to switch statement"}) }
        return true
    })
    return out
}
func isPartOfElseIf(ctx *Context, target *ast.IfStmt) bool { return false }

