func checkNewDeref(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        u, ok := n.(*ast.UnaryExpr); if !ok || u.Op != token.MUL { return true }
        c, ok := u.X.(*ast.CallExpr); if !ok || !isBuiltinCall(c,"new") || len(c.Args)!=1 { return true }
        typ := exprString(ctx,c.Args[0]); repl := zeroValueForType(c.Args[0], typ)
        out = append(out, Diag{Pos:u.Pos(), Message:fmt.Sprintf("replace `%s` with `%s`", exprString(ctx,u), repl)})
        return true
    })
    return out
}
func zeroValueForType(e ast.Expr, typ string) string {
    switch typ { case "bool": return "false"; case "string": return "\"\""; case "float32","float64": return "0.0"; case "complex64","complex128": return "0i" }
    ints := map[string]bool{"int":true,"int8":true,"int16":true,"int32":true,"int64":true,"uint":true,"uint8":true,"uint16":true,"uint32":true,"uint64":true,"uintptr":true,"byte":true,"rune":true}
    if ints[typ] { return "0" }
    switch e.(type) { case *ast.StarExpr: return fmt.Sprintf("(%s)(nil)", typ); case *ast.ArrayType: if strings.HasPrefix(typ,"[]") { return typ+"(nil)" }; return typ+"{}"; case *ast.MapType, *ast.ChanType, *ast.FuncType, *ast.InterfaceType: return typ+"(nil)" }
    return typ+"{}"
}

func checkOctalLiteral(ctx *Context) []Diag { var out []Diag; walkFiles(ctx, func(n ast.Node) bool { lit,ok:=n.(*ast.BasicLit); if ok && lit.Kind==token.INT && len(lit.Value)>1 && strings.HasPrefix(lit.Value,"0") && !strings.HasPrefix(lit.Value,"0x") && !strings.HasPrefix(lit.Value,"0X") && !strings.HasPrefix(lit.Value,"0o") && !strings.HasPrefix(lit.Value,"0O") && !strings.HasPrefix(lit.Value,"0b") { out=append(out,Diag{Pos:lit.Pos(),Message:fmt.Sprintf("use new octal literal style, %s -> 0o%s", lit.Value, strings.TrimPrefix(lit.Value,"0"))}) }; return true }); return out }

func checkOffBy1(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
