        if exprString(ctx,ix.X) == exprString(ctx,c.Args[0]) {
            if tv, ok := ctx.Info.Types[ix.X]; ok && tv.Type != nil {
                _, isSlice := tv.Type.Underlying().(*types.Slice); _, isArray := tv.Type.Underlying().(*types.Array); if !isSlice && !isArray { return true }
            }
            out = append(out, Diag{Pos:ix.Pos(), Message:fmt.Sprintf("index expr always panics; maybe you wanted %s[len(%s)-1]?", exprString(ctx,ix.X), exprString(ctx,ix.X))})
