    return out
}
func singleNonDefault(list []ast.Stmt) bool { if len(list)!=1 {return false}; cc,ok:=list[0].(*ast.CaseClause); return ok && cc.List!=nil }

func checkSloppyLen(ctx *Context) []Diag {
