func checkTypeSwitchVar(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        ts, ok := n.(*ast.TypeSwitchStmt); if !ok { return true }
        varName := ""
        if es, ok := ts.Assign.(*ast.ExprStmt); ok { if ta,ok:=es.X.(*ast.TypeAssertExpr); ok { if id,ok:=ta.X.(*ast.Ident); ok { varName=id.Name } } }
        if varName == "" { return true }
        count := 0
        for _, st := range ts.Body.List { cc:=st.(*ast.CaseClause); if len(cc.List)!=1 {continue}; pat:=fmt.Sprintf("%s.(%s)", varName, exprString(ctx,cc.List[0])); found:=false; for _, bs := range cc.Body { if strings.Contains(exprString(ctx,bs), pat) {found=true; break} }; if found { count++ } }
