            if p, ok := e.X.(*ast.ParenExpr); ok { if u,ok:=p.X.(*ast.UnaryExpr); ok && u.Op==token.MUL { out=append(out,Diag{Pos:e.Pos(),Message:fmt.Sprintf("could simplify %s to %s.%s", exprString(ctx,e), exprString(ctx,u.X), e.Sel.Name)}) } }
        case *ast.IndexExpr:
            if p, ok := e.X.(*ast.ParenExpr); ok { if u,ok:=p.X.(*ast.UnaryExpr); ok && u.Op==token.MUL { out=append(out,Diag{Pos:e.Pos(),Message:fmt.Sprintf("could simplify %s to %s[%s]", exprString(ctx,e), exprString(ctx,u.X), exprString(ctx,e.Index))}) } }
        }
        return true
    })
    return out
}

func checkUnlambda(ctx *Context) []Diag {
    var out []Diag
    walkFiles(ctx, func(n ast.Node) bool {
        fl, ok := n.(*ast.FuncLit); if !ok || len(fl.Body.List)!=1 { return true }
        ret, ok := fl.Body.List[0].(*ast.ReturnStmt); if !ok || len(ret.Results)!=1 { return true }
        c, ok := ret.Results[0].(*ast.CallExpr); if !ok { return true }
        var params []string
        if fl.Type.Params != nil { for _, f := range fl.Type.Params.List { for _, id := range f.Names { params=append(params,id.Name) } } }
        if len(params) != len(c.Args) { return true }
        for i,a := range c.Args { if !isIdent(a, params[i]) { return true } }
        out = append(out, Diag{Pos:fl.Pos(), Message:fmt.Sprintf("replace `%s` with `%s`", exprString(ctx,fl), exprString(ctx,c.Fun))})
