func checkBuiltinShadow(ctx *Context) []Diag {
	var out []Diag
	walkFiles(ctx, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok || as.Tok != token.DEFINE { return true }
		for _, e := range as.Lhs {
