			case *ast.FuncDecl:
				if predeclaredNames[d.Name.Name] { out = append(out, Diag{Pos: d.Name.Pos(), Message: fmt.Sprintf("shadowing of predeclared identifier: %s", d.Name.Name)}) }
			case *ast.GenDecl:
				for _, sp := range d.Specs {
					switch x := sp.(type) {
