			for _, c := range cg.List {
				text := c.Text
				idx := strings.Index(text, "nolint")
				if idx < 0 { continue }
				after := strings.TrimSpace(text[idx+len("nolint"):])
				if after == "" || strings.HasPrefix(after, ":") { out = append(out, Diag{Pos: c.Pos(), Message: "include an explanation for nolint directive"}) }
